from __future__ import print_function
from builtins import str, range, object
import os
import time
from stat import S_ISDIR
import paramiko
import subprocess
from taf.ul.trs_e2e_fw.lib.utils.exception.robot_exception import SSHException
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str


class Communicator(object):
    client = None
    INSTANCE = None
    ssh_object = {}

    def __init__(self):
        if self.INSTANCE is not None:
            raise ValueError("A communicator instance already exists")
        else:
            self.client = paramiko.SSHClient()
            self.client.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    @classmethod
    def get_instance(cls):
        """

        Returns: Communicator class object

        """
        return Communicator()
        # if cls.INSTANCE is None:
        #     cls.INSTANCE = Communicator()
        # return cls.INSTANCE

    def connect_to_remote_machine(self, ip, username, password, port=22):
        """
        This function is used to login to remote machine with appropriate credentials. If authentication fails
        or connection fails for some other reason appropriate exception will be thrown.
        Args:
            ip: ip of the machine
            username: username through which we want to login to  the machine
            password: password for corresponding username

        Returns:

        """
        for i in range(5):
            try:
                self.client.connect(ip, username=username, password=password, banner_timeout=60, port=port)
                break
            except paramiko.BadHostKeyException as e:
                self.client.get_host_keys().clear()
                self.client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
                self.client.connect(ip, username=username, password=password, banner_timeout=60, port=port)
                break
            except paramiko.SSHException as e:
                time.sleep(2)
        else:
            self.client.close()
            self.client = None
            SSHException("SSH to " + ip + " failed after 5 retries with error :: " + str(e))

    def execute_command_remotely(self, ip, username, password, command, port=22):
        """

        Args:
            ip:
            username:
            password:
            command:

        Returns: A tuple in case of failure

        """
        try:
            self.connect_to_remote_machine(ip, username, password, port)
            self.client.exec_command(command)
            time.sleep(2)
            self.client.close()
            return 0, None
        except Exception as e:
            self.client.close()
            return 1, str(e)

    def execute_command_remotely_and_verify(self, ip, username, password, command, pty=False, port=22):
        """
        Execute the command in remote machine, get the output and execution status.
        Args:
            ip:
            username:
            password:
            command:
            pty:

        Returns: Tuple (<Output of execution> , <exit status of command>)

        """
        try:
            self.connect_to_remote_machine(ip, username, password, port)
            stdin, stdout, stderr = self.client.exec_command(command, get_pty=pty)
            output = decode_str(stdout.read())
            status = stdout.channel.recv_exit_status()
            self.client.close()
            return output, status
        except Exception as e:
            self.client.close()
            return str(e), 1

    def execute_commands_remotely_and_verify(self, ip, username, password, commands, pty=False):
        """
        Execute the command in remote machine, get the output and execution status.
        Args:
            ip:
            username:
            password:
            commands:
            pty:

        Returns: Tuple (<Output of execution> , <exit status of command>)

        """
        result = list()
        try:
            self.connect_to_remote_machine(ip, username, password)
            for command in commands:
                stdin, stdout, stderr = self.client.exec_command(command, get_pty=pty)
                output = decode_str(stdout.read())
                status = stdout.channel.recv_exit_status()
                result.append((str(output).strip(), status))
            self.client.close()
            print("hi")
            print(type(result))
            return result
        except Exception as e:
            self.client.close()
            raise SSHException("Remote command execute and verify failed: {}".format(e))

    def command_executor(self, command):
        """
        Note: Can be optimized in python 3
        """
        try:
            process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            output, error = process.communicate()
            return decode_str(output), decode_str(error), process.returncode
        except Exception as e:
            raise Exception(str(e))

    def sftp_walk(self, sftp, remotepath):
        path = remotepath
        files = []
        folders = []
        for f in sftp.listdir_attr(remotepath):
            if S_ISDIR(f.st_mode):
                folders.append(f.filename)
            else:
                # if
                files.append(f.filename)
        # print (path,folders,files)
        yield path, folders, files
        for folder in folders:
            new_path = remotepath + "/" + folder
            for x in self.sftp_walk(sftp, new_path):
                yield x

    def copy_file_from_linux(self, ip, username, password, remote_file, local_path):
        """
        Copy a file from linux to local machine.
        Args:
            ip:
            username:
            password:
            remote_file:
            local_path:

        Returns:

        """
        self.connect_to_remote_machine(ip, username, password)
        sftp = self.client.open_sftp()
        sftp.get(remote_file, local_path)
        sftp.close()
        self.client.close()

    def copy_file_to_linux(self, ip, username, password, local_path, remote_file):
        """
        Copy a file from linux to local machine.
        Args:
            ip:
            username:
            password:
            local_path:
            remote_file:

        Returns:

        """
        self.connect_to_remote_machine(ip, username, password)
        sftp = self.client.open_sftp()
        sftp.put(local_path, remote_file)
        sftp.close()
        self.client.close()

    def copy_folder_from_linux(self, ip, username, password, remote_folder, local_folder):
        """
            Copy a folder recursively from linux to local machine.
        Args:
            ip:
            username:
            password:
            remote_folder:
            local_folder:

        Returns:

        """
        self.connect_to_remote_machine(ip, username, password)
        sftp = self.client.open_sftp()
        sftp.chdir(os.path.split(remote_folder)[0])
        parent = os.path.split(remote_folder)[1]
        try:
            os.mkdir(local_folder)
        except Exception:
            pass
        for walker in self.sftp_walk(sftp, parent):
            try:
                os.mkdir(os.path.join(local_folder, walker[0]))
            except Exception:
                pass
            for file in walker[2]:
                try:
                    sftp.get(walker[0] + "/" + file, local_folder + "/" + walker[0] + "/" + file)
                except Exception:
                    print("Failed in copying " + walker[0] + "/" + file)
                    pass
        sftp.close()
        self.client.close()

    def execute_command_through_transport_api(self, hostname, username, password, command, port=22):
        client = paramiko.Transport(hostname, port)
        client.connect(username=username, password=password)
        session = client.open_channel(kind='session')
        session.exec_command(command)
        session.makefile('wb')
        stdout = session.makefile('rb')
        enb_data = decode_str(stdout.read())
        return enb_data


